import axios from 'axios';

const API_BASE_URL = 'http://localhost:8080/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Interceptor pour ajouter le token JWT
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Interceptor pour gérer les erreurs
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// Auth Service
export const authService = {
  login: (credentials) => api.post('/auth/login', credentials),
  register: (data) => api.post('/auth/register', data),
  validateToken: () => api.get('/auth/validate'),
  getUsers: () => api.get('/auth/users'),
  updateUser: (id, data) => api.put(`/auth/users/${id}`, data),
  deleteUser: (id) => api.delete(`/auth/users/${id}`),
};

// Student Service
export const studentService = {
  getAll: () => api.get('/students'),
  getById: (id) => api.get(`/students/${id}`),
  create: (data) => api.post('/students', data),
  update: (id, data) => api.put(`/students/${id}`, data),
  delete: (id) => api.delete(`/students/${id}`),
  getGrades: (studentId) => api.get(`/students/grades/student/${studentId}`),
  createGrade: (data) => api.post('/students/grades', data),
};

// Teacher Service
export const teacherService = {
  getAll: () => api.get('/teachers'),
  getById: (id) => api.get(`/teachers/${id}`),
  create: (data) => api.post('/teachers', data),
  update: (id, data) => api.put(`/teachers/${id}`, data),
  delete: (id) => api.delete(`/teachers/${id}`),
  getAvailabilities: (teacherId) => api.get(`/teachers/${teacherId}/availabilities`),
  addAvailability: (data) => api.post('/teachers/availabilities', data),
};

// Course Service
export const courseService = {
  getAll: () => api.get('/courses'),
  getById: (id) => api.get(`/courses/${id}`),
  create: (data) => api.post('/courses', data),
  update: (id, data) => api.put(`/courses/${id}`, data),
  delete: (id) => api.delete(`/courses/${id}`),
  getPrograms: () => api.get('/courses/programs'),
  createProgram: (data) => api.post('/courses/programs', data),
  enrollStudent: (data) => api.post('/courses/enrollments', data),
  getEnrollmentsByStudent: (studentId) => api.get(`/courses/enrollments/student/${studentId}`),
};

// Schedule Service
export const scheduleService = {
  getAll: () => api.get('/schedules'),
  getById: (id) => api.get(`/schedules/${id}`),
  create: (data) => api.post('/schedules', data),
  delete: (id) => api.delete(`/schedules/${id}`),
  getRooms: () => api.get('/schedules/rooms'),
  createRoom: (data) => api.post('/schedules/rooms', data),
  getAvailableRooms: () => api.get('/schedules/rooms/available'),
};

// Exam Service
export const examService = {
  getAll: () => api.get('/exams'),
  getById: (id) => api.get(`/exams/${id}`),
  create: (data) => api.post('/exams', data),
  update: (id, data) => api.put(`/exams/${id}`, data),
  delete: (id) => api.delete(`/exams/${id}`),
  getResults: (examId) => api.get(`/exams/${examId}/results`),
  submitResult: (data) => api.post('/exams/results', data),
};

// Admin Service
export const adminService = {
  getSettings: () => api.get('/admin/settings'),
  updateSetting: (key, data) => api.put(`/admin/settings/${key}`, data),
  getAuditLogs: () => api.get('/admin/audit-logs'),
  getDashboardStats: () => api.get('/admin/dashboard/stats'),
};

export default api;
